-- Centro Tanner: catálogo completo de políticas (1-133) del Contexto Maestro
-- entregado por Presidencia. Contenido oficial verbatim; solo se calculó
-- categoría, slug y una respuesta corta (primeras oraciones del texto
-- oficial, sin agregar información nueva). Las políticas 134-141 del
-- documento son instrucciones para el agente/implementación, no reglas
-- del club, así que no se publican. La política 142 (Pagos y servicios
-- no acumulables) ya estaba cargada desde antes.
insert into app.policies (
  organization_id, policy_code, slug, title, category, scope, short_answer,
  official_content, keywords, status, requires_acceptance, effective_date, published_at
)
select o.id, v.policy_code, v.slug, v.title, v.category, v.scope, v.short_answer,
  v.official_content, v.keywords, 'published', false, date '2026-09-09', timestamptz '2026-09-09 19:07:52+00'
from public.organizations o
cross join (values
($$TC-081$$, $$grupos-sociales-no-oficiales$$, $$Grupos sociales no oficiales$$, $$familias$$, $$tannery_city$$, $$Grupos creados por padres no son canales oficiales. Tannery City no administra, supervisa permanentemente ni responde por su contenido.$$, $$Grupos creados por padres no son canales oficiales. Tannery City no administra, supervisa permanentemente ni responde por su contenido. Si existe evidencia de amenazas, hostigamiento, discriminación, agresiones o conducta contraria al Código Tanner, el club puede revisar y actuar. No sancionar solo por opiniones o inconformidades legítimas.$$, array[$$grupos$$,$$sociales$$,$$oficiales$$]),
($$TC-082$$, $$avisos-oficiales$$, $$Avisos oficiales$$, $$familias$$, $$tannery_city$$, $$Un aviso publicado mediante canal oficial se considera comunicado. Cada familia es responsable de mantenerse atenta.$$, $$Un aviso publicado mediante canal oficial se considera comunicado. Cada familia es responsable de mantenerse atenta.$$, array[$$avisos$$,$$oficiales$$]),
($$TC-083$$, $$horario-administrativo$$, $$Horario administrativo$$, $$familias$$, $$tannery_city$$, $$Lunes a viernes: 10:00–14:00 y 16:00–19:00 hrs. Objetivo de respuesta: máximo 24 horas hábiles.$$, $$Lunes a viernes: 10:00–14:00 y 16:00–19:00 hrs. Objetivo de respuesta: máximo 24 horas hábiles.$$, array[$$horario$$,$$administrativo$$]),
($$TC-084$$, $$encuestas$$, $$Encuestas$$, $$familias$$, $$tannery_city$$, $$Las encuestas a familias son consultivas. Decisión final deportiva/operativa corresponde a Dirección, Área Deportiva o Presidencia según el tema.$$, $$Las encuestas a familias son consultivas. Decisión final deportiva/operativa corresponde a Dirección, Área Deportiva o Presidencia según el tema.$$, array[$$encuestas$$]),
($$TC-085$$, $$reporte-de-incidentes$$, $$Reporte de incidentes$$, $$seguridad$$, $$tannery_city$$, $$Canal: WhatsApp oficial de Tannery City. No se requiere módulo independiente de denuncias en Tanner OS.$$, $$Canal: WhatsApp oficial de Tannery City. No se requiere módulo independiente de denuncias en Tanner OS. Objetivo: conservar evidencia, fecha y seguimiento.$$, array[$$reporte$$,$$incidentes$$]),
($$TC-086$$, $$foto-interna$$, $$Foto interna$$, $$privacidad$$, $$tannery_city$$, $$Foto del jugador obligatoria para identificación y operación interna.$$, $$Foto del jugador obligatoria para identificación y operación interna.$$, array[$$foto$$,$$interna$$]),
($$TC-087$$, $$uso-de-imagen$$, $$Uso de imagen$$, $$privacidad$$, $$tannery_city$$, $$Marketing/publicidad es opcional. Tutor debe aceptar o negar expresamente. Negarse no afecta derecho a entrenar.$$, $$Marketing/publicidad es opcional. Tutor debe aceptar o negar expresamente. Negarse no afecta derecho a entrenar.$$, array[$$uso$$,$$imagen$$]),
($$TC-088$$, $$fotos-videos-del-staff$$, $$Fotos y videos del staff$$, $$privacidad$$, $$tannery_city$$, $$Entrenadores pueden tomar material con fines deportivos legítimos. Debe respetar autorizaciones, transferirse a almacenamiento oficial y no conservarse innecesariamente en dispositivos personales.$$, $$Entrenadores pueden tomar material con fines deportivos legítimos. Debe respetar autorizaciones, transferirse a almacenamiento oficial y no conservarse innecesariamente en dispositivos personales. Publicación en cuentas personales solo con autorización vigente de imagen.$$, array[$$fotos$$,$$videos$$,$$staff$$]),
($$TC-089$$, $$fotos-y-videos-de-familias$$, $$Fotos y videos de familias$$, $$privacidad$$, $$tannery_city$$, $$Se permiten para uso personal procurando respetar privacidad, imagen de otros menores e instrucciones del club.$$, $$Se permiten para uso personal procurando respetar privacidad, imagen de otros menores e instrucciones del club.$$, array[$$fotos$$,$$videos$$,$$familias$$]),
($$TC-090$$, $$drones-y-streaming$$, $$Drones y streaming$$, $$privacidad$$, $$tannery_city$$, $$Drones solo con autorización previa. Transmisiones/streaming por terceros requieren autorización.$$, $$Drones solo con autorización previa. Transmisiones/streaming por terceros requieren autorización.$$, array[$$drones$$,$$streaming$$]),
($$TC-091$$, $$uso-de-marca$$, $$Uso de marca$$, $$privacidad$$, $$tannery_city$$, $$No utilizar sin autorización nombre Tannery City, Tannery City Park, escudo, logos, diseños, identidad, jerseys o elementos gráficos para eventos, productos, negocios, patrocinios, campañas, torneos o ventas.$$, $$No utilizar sin autorización nombre Tannery City, Tannery City Park, escudo, logos, diseños, identidad, jerseys o elementos gráficos para eventos, productos, negocios, patrocinios, campañas, torneos o ventas.$$, array[$$uso$$,$$marca$$]),
($$TC-092$$, $$patrocinios$$, $$Patrocinios$$, $$conducta$$, $$tannery_city$$, $$Ninguna familia, jugador, entrenador o tercero puede representar a Tannery City ante una empresa o negociar patrocinio sin autorización.$$, $$Ninguna familia, jugador, entrenador o tercero puede representar a Tannery City ante una empresa o negociar patrocinio sin autorización.$$, array[$$patrocinios$$]),
($$TC-093$$, $$colectas-dinero$$, $$Colectas / dinero$$, $$conducta$$, $$tannery_city$$, $$No solicitar dinero, cooperaciones o colectas usando grupos/nombre Tanner sin autorización.$$, $$No solicitar dinero, cooperaciones o colectas usando grupos/nombre Tanner sin autorización.$$, array[$$colectas$$,$$dinero$$]),
